glsl:
float bayer(vec2 p) {
  vec2 q = mod(p, 4.0);
  int i = int(q.x) + int(q.y) * 4;
  float m[16] = float[16](0.,8.,2.,10.,12.,4.,14.,6.,3.,11.,1.,9.,15.,7.,13.,5.);
  return m[i] / 16.0;
}
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  float px = mix(1.0, 3.0, uAmount);
  float t = bayer(floor(gl_FragCoord.xy / px)) - 0.5;
  vec3 q = floor(c.rgb * 3.0 + t + 0.5) / 3.0;
  return vec4(mix(c.rgb, q, uAmount), c.a);
}
